"  public async evaluateManualPersonaBenchmarkAsync(
    levelJson: LevelJSON,
    deckSize: number,
    seedOffset: number = 42,
    botConfig?: Partial<BotConfig>,
    goldenSeedIds?: number[],
    onProgress?: (desc: string, pct: number) => void
  ): Promise<{
    personaResultsGolden: Record<PersonaType, SimulationMetrics>;
    personaResultsRandom: Record<PersonaType, SimulationMetrics>;
    skillIndex: number;
  }> {
    const personaTypes: PersonaType[] = ['casual', 'medium', 'expert'];
    const personaResultsGolden: Record<PersonaType, SimulationMetrics> = {} as any;
    const personaResultsRandom: Record<PersonaType, SimulationMetrics> = {} as any;

    let pIdx = 0;
    for (const pType of personaTypes) {
      const profile = PERSONA_PRESETS[pType];
      const pConfig = botConfig ? { ...profile.botConfig, ...botConfig } : profile.botConfig;
      pIdx++;
      const pct = Math.round((pIdx / 3) * 100);

      onProgress?.(`Testing ${profile.name} on Golden Seeds (${pct}%)...`, pct - 10);
      personaResultsGolden[pType] = await runSimulationAsync(
        levelJson,
        500,
        deckSize,
        seedOffset,
        pConfig,
        undefined,
        goldenSeedIds && goldenSeedIds.length > 0 ? goldenSeedIds : undefined
      );

      onProgress?.(`Testing ${profile.name} on Random Deals (${pct}%)...`, pct);
      personaResultsRandom[pType] = await runSimulationAsync(
        levelJson,
        500,
        deckSize,
        seedOffset,
        pConfig,
        undefined,
        undefined
      );
    }

    const skillIndex = Math.max(
      0,
      personaResultsGolden.expert.passRate - personaResultsGolden.casual.passRate
    );

    return {
      personaResultsGolden,
      personaResultsRandom,
      skillIndex,
    };
  }"

