"/* ==========================================================================
   Multi-Persona Skill Benchmark (Ultra-Clear & Informative)
   ========================================================================== */

.persona-benchmark-container {
  display: flex;
  flex-direction: column;
  gap: 7px;
  flex: 1;
}

.persona-skill-summary-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-sm);
  padding: 5px 8px;
}

.skill-summary-left {
  display: flex;
  align-items: center;
  gap: 6px;
}

.skill-summary-lbl {
  font-size: 10.5px;
  font-weight: 700;
  color: #e2e8f0;
}

.badge-skill-gap {
  font-size: 10px;
  font-weight: 700;
  padding: 1.5px 6px;
  border-radius: 10px;
  background: rgba(34, 197, 94, 0.15);
  color: #22c55e;
  border: 1px solid rgba(34, 197, 94, 0.35);
  font-family: monospace;
  white-space: nowrap;
}

.skill-summary-sub {
  font-size: 9px;
  color: var(--text-muted);
  font-family: monospace;
}

.persona-cards-stack {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

.persona-card-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-sm);
  padding: 6px 8px;
  border-left: 3px solid transparent;
  transition: all 0.2s ease;
}

.persona-card-item:hover {
  background: rgba(255, 255, 255, 0.03);
  border-color: rgba(255, 255, 255, 0.12);
}

